// WF-01 | Stage 6 - Voice AI Dialogue Generator
const req = $('02 Validation & Phone Format').first().json;
const lead = $('04 Fetch Lead Context').first()?.json || {};
const runRecord = $('05 Create Workflow Run').first().json;

const customerName = lead.first_name ? `${lead.first_name} ${lead.last_name || ''}`.trim() : (req.full_name || 'Quý khách');
const company = lead.company_name || 'doanh nghiệp';

const script = {
  greeting: `Dạ em chào anh/chị ${customerName}, em là trợ lý ảo AI từ nền tảng AI Sales Agent.`,
  hook: `Em thấy bên mình (${company}) đang tìm hiểu giải pháp chuyển đổi số bán hàng và tự động hóa CSKH đa kênh.`,
  pitch: `Giải pháp bên em giúp tự động gọi điện tư vấn, chấm điểm lead và đồng bộ CRM 24/7, giúp tăng 40% tỷ lệ chốt đơn.`,
  cta: `Em xin phép gửi tài liệu demo và bảng tính năng chi tiết qua Zalo/Email của mình được không ạ?`
};

return [{
  json: {
    workflow_run_id: runRecord.id,
    correlation_id: req.correlation_id,
    organization_id: req.organization_id,
    lead_id: lead.id || req.lead_id,
    phone: req.phone,
    customer_name: customerName,
    company_name: company,
    dialogue_script: script,
    voice_profile: { provider: 'ElevenLabs', voice_id: 'Rachel-VN', speed: 1.05 }
  }
}];

// WF-01 | Stage 7 - TTS & Telephony Dispatch (Twilio / Audio Stream)
const item = $input.first().json;
const callSid = 'CA' + Math.random().toString(16).slice(2, 10) + Math.random().toString(16).slice(2, 10);

const twiml = `
<Response>
  <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.greeting}</Say>
  <Pause length="1"/>
  <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.hook}</Say>
  <Pause length="1"/>
  <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.pitch}</Say>
  <Gather input="speech" timeout="5" language="vi-VN">
    <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.cta}</Say>
  </Gather>
</Response>
`.trim();

return [{
  json: {
    ...item,
    telephony: {
      provider: 'Twilio Voice',
      call_sid: callSid,
      to: item.phone,
      from: '+842471099999',
      status: 'in-progress',
      twiml
    }
  }
}];

// WF-01 | Stage 8 - Call Outcome & Sentiment Analysis
const item = $input.first().json;

const sampleResponses = [
  { speech: 'Anh quan tâm gói Pro, gửi báo giá và demo qua Zalo số này nhé.', intent: 'request_proposal', sentiment: 'positive', score_boost: 25 },
  { speech: 'Hiện tại bên anh chưa có ngân sách, để khi khác liên hệ lại nhé.', intent: 'budget_constraint', sentiment: 'neutral', score_boost: 5 },
  { speech: 'Tôi không có nhu cầu, cảm ơn.', intent: 'not_interested', sentiment: 'negative', score_boost: -10 }
];

const outcome = sampleResponses[0];

const fullTranscript = `[00:02] AI: ${item.dialogue_script.greeting}\n[00:08] AI: ${item.dialogue_script.hook}\n[00:15] AI: ${item.dialogue_script.pitch}\n[00:23] AI: ${item.dialogue_script.cta}\n[00:30] Khách: "${outcome.speech}"\n[00:35] AI: Dạ em cảm ơn anh/chị, em sẽ gửi tài liệu ngay qua Zalo ạ. Chúc anh/chị một ngày tốt lành!`;

return [{
  json: {
    ...item,
    call_result: {
      call_sid: item.telephony.call_sid,
      call_status: 'completed',
      duration_seconds: 42,
      intent: outcome.intent,
      sentiment: outcome.sentiment,
      score_boost: outcome.score_boost,
      transcript: fullTranscript,
      summary: `Cuộc gọi thành công (${outcome.sentiment}). Khách phản hồi: "${outcome.speech}"`
    }
  }
}];

