// WF-01 | Stage 13 - Success Log
const data = $('08 Call Analysis & Transcript').first().json;

return [{
  json: {
    status: 'success',
    data: {
      call_sid: data.call_result.call_sid,
      call_status: data.call_result.call_status,
      duration: data.call_result.duration_seconds,
      customer_phone: data.phone,
      customer_name: data.customer_name,
      intent: data.call_result.intent,
      sentiment: data.call_result.sentiment,
      transcript_summary: data.call_result.summary,
      workflow_run_id: data.workflow_run_id,
      correlation_id: data.correlation_id
    }
  }
}];

// WF-01 | Stage 16 - Error Handle
const err = $input.first().json?.execution?.error || {};
const failedNode = $input.first().json?.execution?.lastNodeExecuted || 'unknown';

let workflowRunId = null;
try { workflowRunId = $('05 Create Workflow Run').first()?.json?.id || null; } catch (e) {}

return [{
  json: {
    workflowRunId,
    error: { message: err.message || 'Call execution failed', failedNode, timestamp: new Date().toISOString() }
  }
}];
